`timescale 1ns/1ps

module PATTERN (
  // To DUT
  output reg        clk,
  output reg        rst_n,
  output reg        in_valid_data,
  output reg        in_valid_param,
  output reg  [7:0] data,
  output reg  [3:0] index,
  output reg  [4:0] QP,
  output reg        mode,
  // From DUT
  input  wire       out_valid,
  input  wire [31:0]out_value
);

//================================================================
// Parameters
//================================================================
parameter CYCLE      = 20.0;  
parameter RST_CYCLES = 3;      
parameter LAT_MAX    = 10000;   

localparam F          = 16;      
localparam H          = 32;
localparam W          = 32;
localparam PIX_PER_FR = H*W;  
localparam PIX_ALL    = F*PIX_PER_FR;
localparam SETS       = 16;      
localparam Z_PER_SET  = H*W;    


string FILE_IN  = "../00_TESTBED/input.txt";   
string FILE_OUT = "../00_TESTBED/output.txt";  
string arg_in, arg_out;

integer fin, fout;
integer pat_cnt, pat_total;
integer rc;

// internal bookkeeping
integer cyc;
integer sent_pixels;
integer set_id;
integer mb_i;
integer z_need, z_got;
integer latency_cnt;
integer expect_Z;
integer cyc_wo_in;

// for readable errors
localparam ERR_FILE     = 1;
localparam ERR_PROTO    = 2;
localparam ERR_MISMATCH = 3;
localparam ERR_OVERLAP  = 4;
localparam ERR_LATENCY  = 5;
localparam ERR_OUZERO   = 6;

//================================================================
// Clock
//================================================================
initial clk = 0;
always #(CYCLE/2.0) clk = ~clk;

//================================================================
// Reset & drive process
//================================================================
initial begin
  in_valid_data  = 0;
  in_valid_param = 0;
  data           = 'bx;
  index          = 'bx;
  QP             = 'bx;
  mode           = 'bx;
  rst_n          = 1'b1;

  if ($value$plusargs("INPUT=%s", arg_in))  FILE_IN  = arg_in;
  if ($value$plusargs("OUTPUT=%s", arg_out)) FILE_OUT = arg_out;

  fin  = $fopen(FILE_IN , "r");
  if (fin == 0)  fail_and_quit(ERR_FILE, $sformatf("Cannot open %s", FILE_IN));
  fout = $fopen(FILE_OUT, "r");
  if (fout == 0) fail_and_quit(ERR_FILE, $sformatf("Cannot open %s", FILE_OUT));

  rc = $fscanf(fin,  "%d", pat_total);
  if (rc!=1) fail_and_quit(ERR_FILE, "Bad or missing pattern count in input.txt");
  if ($fscanf(fout, "%d", rc)!=1) fail_and_quit(ERR_FILE, "Bad or missing pattern count in output.txt");
  if (rc != pat_total) fail_and_quit(ERR_FILE, $sformatf("input/output PATTERN_COUNT mismatch: in=%0d out=%0d", pat_total, rc));

  banner_intro();

  force clk = 0;
  #(10);  rst_n=0;

  #(3*CYCLE);

  rst_n = 1'b1;
  #(CYCLE);
  release clk;

  @(negedge clk);
  @(negedge clk);

  cyc = 0;
  pat_cnt = 0;
  cyc_wo_in = 0;
  for (pat_cnt = 0; pat_cnt < pat_total; pat_cnt = pat_cnt + 1) begin
    drive_frames_from_file();
    repeat(2) @(negedge clk);

    for (set_id = 0; set_id < SETS; set_id = set_id + 1) begin
      drive_set_params_from_file();
      latency_cnt = 0;
      check_outputs_for_one_set();
      $display("\033[32mPATTERN %d SET %d PASS, CYCLE = %d", pat_cnt, set_id, latency_cnt);

      repeat($urandom_range(2, 4)) @(negedge clk);
    end

    repeat($urandom_range(2, 4)) @(negedge clk);
  end
  pass_and_finish();
end

//================================================================
// Tasks
//================================================================

