task banner_intro; begin
  $display("\n==============================================================");
  $display("  File-driven PATTERN starting...");
  $display("  CYCLE=%.1f ns  LAT_MAX=%0d cycles", CYCLE, LAT_MAX);
  $display("  input : %s", FILE_IN);
  $display("  output: %s", FILE_OUT);
  $display("==============================================================\n");
end endtask

task banner_pass; begin
  $display("==============================================================");
  $display("    PASS – All %0d pattern(s) matched expected outputs", pat_total);
  $display("==============================================================\n");
end endtask

task drive_frames_from_file; integer i; integer pix; begin
  if (out_valid) fail_and_quit(ERR_OVERLAP, "DUT asserted out_valid during frame input phase");

  in_valid_data = 1'b1;
  for (i = 0; i < PIX_ALL; i = i + 1) begin
    if ($fscanf(fin, "%d", pix) != 1) fail_and_quit(ERR_FILE, "input.txt exhausted while reading frame pixels");

    if (pix < 0) pix = 0; else if (pix > 255) pix = 255;
    data = pix[7:0];

    @(negedge clk);
    cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;

    if (out_valid) fail_and_quit(ERR_OVERLAP, "out_valid overlapped with in_valid_data");
  end
  in_valid_data = 1'b0; data = 'bx;
end endtask

task drive_set_params_from_file; integer v_idx, v_qp, m0, m1, m2, m3; begin
  if (out_valid) fail_and_quit(ERR_OVERLAP, "DUT asserted out_valid during param input phase");

  if ($fscanf(fin, "%d %d", v_idx, v_qp) != 2)
    fail_and_quit(ERR_FILE, "input.txt exhausted while reading index/QP");

  if ($fscanf(fin, "%d %d %d %d", m0, m1, m2, m3) != 4)
    fail_and_quit(ERR_FILE, "input.txt exhausted while reading 4 mode bits");

  index = v_idx[3:0];
  QP    = v_qp[4:0];
  in_valid_param = 1'b1;
  mode = m0[0]; 
  @(negedge clk); cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;

  index= 'bx; QP= 'bx;

  mode = m1[0]; @(negedge clk); cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;
  mode = m2[0]; @(negedge clk); cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;
  mode = m3[0]; @(negedge clk); cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;


  in_valid_param = 1'b0; index='bx; QP='bx; mode='bx;

  repeat(2) @(negedge clk); cyc = cyc + 2; cyc_wo_in = cyc_wo_in + 2;
end endtask

task check_outputs_for_one_set; begin
  z_need = Z_PER_SET; z_got = 0; latency_cnt = 0;

  while (!out_valid) begin
    if (out_value !== 32'd0) fail_and_quit(ERR_OUZERO, $sformatf("out_value(%0d) != 0 when out_valid=0", out_value));

    if (latency_cnt > LAT_MAX)
      fail_and_quit(ERR_LATENCY, $sformatf("Latency exceeded %0d cycles before first out_valid", LAT_MAX));

    @(negedge clk); cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1; latency_cnt = latency_cnt + 1;
  end

  while (z_got < z_need) begin
    if (out_valid) begin
      if ($fscanf(fout, "%d", expect_Z) != 1)
        fail_and_quit(ERR_FILE, "output.txt exhausted while expecting more Z");
      if ($signed(out_value) !== $signed(expect_Z)) begin
        fail_and_quit(ERR_MISMATCH,
          $sformatf("Z mismatch (set %0d, idx %0d): DUT=%0d expect=%0d", set_id, z_got, $signed(out_value), $signed(expect_Z)));
      end
      z_got = z_got + 1;
    end else begin
      if (out_value !== 32'd0)
        fail_and_quit(ERR_OUZERO, $sformatf("out_value(%0d) != 0 when out_valid=0", out_value));
        latency_cnt = latency_cnt + 1;
        if (latency_cnt > LAT_MAX)
          fail_and_quit(ERR_LATENCY, $sformatf("Latency exceeded %0d cycles before first out_valid", LAT_MAX));
    end

    @(negedge clk); 
    cyc = cyc + 1; cyc_wo_in = cyc_wo_in + 1;
  end
end endtask

